public sealed class EquipmentUsageHttpTests
{
    [Theory]
    [InlineData("")]
    [InlineData(" ")]
    public async Task Setup_requires_an_explicit_database(string connection)
    {
        var error = await Assert.ThrowsAsync<InvalidOperationException>(() =>
            Setup.Program.Main(["ConnectionStrings:DefaultConnection=" + connection]));

        Assert.Equal("ConnectionStrings:DefaultConnection is required.", error.Message);
    }

    [Fact]
    public async Task Usage_post_replay_repost_and_unpost_preserve_append_only_history_and_totals()
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        using var admin = await host.CreateClientAsync("administrator");
        using var reader = await host.CreateClientAsync("reader");
        var equipment = await PostAsync<CatalogItemDto>(admin, "/api/catalogs/example.equipment", Payload(("display", "Metered bench")));
        var draft = await PostAsync<DocumentDto>(admin, "/api/documents/" + EquipmentUsageDefinitions.DocumentCode, new RecordPayload());
        var path = "/api/documents/" + EquipmentUsageDefinitions.DocumentCode + "/" + draft.Id;
        var state = await StateAsync(admin, path);
        using var incomplete = await ExecutePostAsync(admin, path, state.DocumentVersion, "missing-usage");
        Assert.Equal(HttpStatusCode.BadRequest, incomplete.StatusCode);
        Assert.Empty(await HistoryAsync(host, draft));

        using var updated = await admin.PutAsJsonAsync(path, Payload(("equipment_id", equipment.Id), ("hours", 6.25m)));
        await EnsureSuccessAsync(updated);
        state = await StateAsync(admin, path);
        using var denied = await ExecutePostAsync(reader, path, state.DocumentVersion, "denied-usage");
        Assert.Equal(HttpStatusCode.Forbidden, denied.StatusCode);

        using var postedResponse = await ExecutePostAsync(admin, path, state.DocumentVersion, "post-usage");
        var posted = await ReadActionAsync(postedResponse);
        Assert.Equal(DocumentStatus.Posted, posted.Document.Status);
        var original = Assert.Single(await HistoryAsync(host, draft));
        Assert.False(original.IsStorno);
        Assert.Equal(6.25m, original.Values["hours"]);
        await using (var setupScope = host.Services.CreateAsyncScope())
        {
            var defaults = ActivatorUtilities.CreateInstance<EquipmentDefaults>(setupScope.ServiceProvider);
            await defaults.ApplyAsync(CancellationToken.None);
            var registers = setupScope.ServiceProvider.GetRequiredService<IOperationalRegisterManagementService>();
            var register = OperationalRegisterId.FromCode(EquipmentUsageDefinitions.RegisterCode);
            await Assert.ThrowsAsync<OperationalRegisterResourcesAppendOnlyViolationException>(() =>
                registers.ReplaceResourcesAsync(register, []));
            await Assert.ThrowsAsync<OperationalRegisterDimensionRulesAppendOnlyViolationException>(() =>
                registers.ReplaceDimensionRulesAsync(register, []));
        }
        Assert.Equal(original.MovementId, Assert.Single(await HistoryAsync(host, draft)).MovementId);
        var effects = await admin.GetFromJsonAsync<DocumentEffectsDto>(path + "/effects", Json);
        var effect = Assert.Single(effects!.OperationalRegisterMovements);
        Assert.Equal(equipment.Id, Assert.Single(effect.Dimensions).ValueId);
        Assert.Equal("Metered bench", Assert.Single(effect.Dimensions).Display);
        Assert.Equal(6.25m, Assert.Single(effect.Resources).Value);
        Assert.Empty(effects.AccountingEntries);
        Assert.Empty(effects.ReferenceRegisterWrites);

        using var replay = await ExecutePostAsync(admin, path, state.DocumentVersion, "post-usage");
        Assert.Equal(posted.ExecutionId, (await ReadActionAsync(replay)).ExecutionId);
        Assert.Single(await HistoryAsync(host, draft));

        using var repost = await ExecuteActionAsync(admin, path, "repost", posted.DocumentVersion, "repost-usage");
        var reposted = await ReadActionAsync(repost);
        var afterRepost = await HistoryAsync(host, draft);
        Assert.Equal(3, afterRepost.Count);
        Assert.Contains(afterRepost, row => row.MovementId == original.MovementId && !row.IsStorno);
        Assert.Equal(6.25m, Net(afterRepost));
        await AssertProjectionAsync(host, 6.25m);

        using var stale = await ExecuteActionAsync(admin, path, "unpost", posted.DocumentVersion, "stale-usage");
        Assert.Equal(HttpStatusCode.Conflict, stale.StatusCode);
        Assert.Equal(afterRepost.Select(row => row.MovementId), (await HistoryAsync(host, draft)).Select(row => row.MovementId));
        using var unpost = await ExecuteActionAsync(admin, path, "unpost", reposted.DocumentVersion, "unpost-usage");
        var unposted = await ReadActionAsync(unpost);
        Assert.Equal(DocumentStatus.Draft, unposted.Document.Status);
        var history = await HistoryAsync(host, draft);
        Assert.True(history.Count > afterRepost.Count);
        Assert.Equal(afterRepost.Select(row => row.MovementId), history.Take(afterRepost.Count).Select(row => row.MovementId));
        Assert.Equal(0m, Net(history));
        await AssertProjectionAsync(host, 0m);
    }

    [Fact]
    public async Task Equipment_dimensions_keep_paged_turnovers_and_balances_separate()
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        using var admin = await host.CreateClientAsync("administrator");
        var first = await PostAsync<CatalogItemDto>(admin, "/api/catalogs/example.equipment", Payload(("display", "First bench")));
        var second = await PostAsync<CatalogItemDto>(admin, "/api/catalogs/example.equipment", Payload(("display", "Second bench")));
        foreach (var (equipment, hours) in new[] { (first.Id, 2.5m), (first.Id, 1.5m), (second.Id, 5m) })
        {
            var document = await PostAsync<DocumentDto>(admin, "/api/documents/" + EquipmentUsageDefinitions.DocumentCode,
                Payload(("equipment_id", equipment), ("hours", hours)));
            var path = "/api/documents/" + EquipmentUsageDefinitions.DocumentCode + "/" + document.Id;
            var state = await StateAsync(admin, path);
            using var posted = await ExecutePostAsync(admin, path, state.DocumentVersion, document.Id.ToString());
            await EnsureSuccessAsync(posted);
        }

        await using var scope = host.Services.CreateAsyncScope();
        var register = OperationalRegisterId.FromCode(EquipmentUsageDefinitions.RegisterCode);
        var maintenance = scope.ServiceProvider.GetRequiredService<IOperationalRegisterAdminMaintenanceService>();
        Assert.Equal(1, await maintenance.FinalizeRegisterDirtyAsync(register));
        Assert.Equal(0, await maintenance.FinalizeRegisterDirtyAsync(register));
        var reads = scope.ServiceProvider.GetRequiredService<IOperationalRegisterReadService>();
        foreach (var read in new Func<OperationalRegisterMonthlyProjectionPageRequest, CancellationToken,
                     Task<OperationalRegisterMonthlyProjectionPage>>[] { reads.GetTurnoversPageAsync, reads.GetBalancesPageAsync })
        {
            var request = new OperationalRegisterMonthlyProjectionPageRequest(register,
                CurrentMonth.AddMonths(-1), CurrentMonth.AddMonths(1), PageSize: 1);
            var values = new Dictionary<Guid, decimal>();
            OperationalRegisterMonthlyProjectionPage page;
            do
            {
                page = await read(request, CancellationToken.None);
                var row = Assert.Single(page.Lines);
                var dimension = Assert.Single(row.Dimensions);
                Assert.Equal(EquipmentDefinitions.EquipmentDimensionId, dimension.DimensionId);
                Assert.True(values.TryAdd(dimension.ValueId, row.Values["hours"]));
                Assert.InRange(values.Count, 1, 2);
                request = request with { Cursor = page.NextCursor };
            } while (page.HasMore);

            Assert.Equal(4m, values[first.Id]);
            Assert.Equal(5m, values[second.Id]);
            var filtered = await read(request with
            {
                Cursor = null,
                Dimensions = [new DimensionValue(EquipmentDefinitions.EquipmentDimensionId, first.Id)]
            }, CancellationToken.None);
            Assert.Equal(4m, Assert.Single(filtered.Lines).Values["hours"]);
            Assert.False(filtered.HasMore);
        }
    }

    [Fact]
    public async Task Failure_after_register_writes_rolls_back_movements_status_and_version()
    {
        var failure = new AuditFailure();
        await using var host = new InspectionHost(configureServices: services =>
        {
            services.AddScoped<PostgresAuditEventWriter>();
            services.AddScoped<IAuditEventWriter>(provider =>
                new FailingAuditWriter(provider.GetRequiredService<PostgresAuditEventWriter>(),
                    provider.GetRequiredService<IOperationalRegisterReadService>(), failure));
        });
        await host.StartAsync();
        using var admin = await host.CreateClientAsync("administrator");
        var equipment = await PostAsync<CatalogItemDto>(admin, "/api/catalogs/example.equipment", Payload(("display", "Rollback bench")));
        var draft = await PostAsync<DocumentDto>(admin, "/api/documents/" + EquipmentUsageDefinitions.DocumentCode,
            Payload(("equipment_id", equipment.Id), ("hours", 3m)));
        var path = "/api/documents/" + EquipmentUsageDefinitions.DocumentCode + "/" + draft.Id;
        var before = await StateAsync(admin, path);
        using var response = await ExecutePostAsync(admin, path, before.DocumentVersion, "rollback-usage");
        Assert.Equal(HttpStatusCode.InternalServerError, response.StatusCode);
        Assert.True(failure.Triggered);
        Assert.True(failure.SawMovement);
        var after = await StateAsync(admin, path);
        Assert.Equal(DocumentStatus.Draft, after.Document.Status);
        Assert.Equal(before.DocumentVersion, after.DocumentVersion);
        Assert.Empty(await HistoryAsync(host, draft));
        await AssertNoEffectsAsync(admin, path);
    }

    private static async Task<DocumentEditorStateDto> StateAsync(HttpClient client, string path)
        => (await client.GetFromJsonAsync<DocumentEditorStateDto>(path + "/editor-state", Json))!;

    private static DateOnly CurrentMonth
    {
        get
        {
            var today = DateOnly.FromDateTime(DateTime.UtcNow);
            return new DateOnly(today.Year, today.Month, 1);
        }
    }

    private static decimal Net(IEnumerable<OperationalRegisterMovementQueryReadRow> rows)
        => rows.Sum(row => (row.IsStorno ? -1m : 1m) * row.Values["hours"]);

    private static async Task<List<OperationalRegisterMovementQueryReadRow>> HistoryAsync(InspectionHost host, DocumentDto document)
    {
        await using var scope = host.Services.CreateAsyncScope();
        var reads = scope.ServiceProvider.GetRequiredService<IOperationalRegisterReadService>();
        var request = new OperationalRegisterMovementsPageRequest(OperationalRegisterId.FromCode(EquipmentUsageDefinitions.RegisterCode),
            CurrentMonth.AddMonths(-1), CurrentMonth.AddMonths(1), DocumentId: document.Id, PageSize: 1);
        var rows = new List<OperationalRegisterMovementQueryReadRow>();
        OperationalRegisterMovementsPage page;
        do
        {
            page = await reads.GetMovementsPageAsync(request);
            rows.AddRange(page.Lines);
            Assert.InRange(rows.Count, 0, 10);
            request = request with { Cursor = page.NextCursor };
        } while (page.HasMore);

        Assert.Equal(rows.Count, rows.Select(row => row.MovementId).Distinct().Count());
        return rows;
    }

    private static async Task AssertProjectionAsync(InspectionHost host, decimal expected)
    {
        await using var scope = host.Services.CreateAsyncScope();
        var register = OperationalRegisterId.FromCode(EquipmentUsageDefinitions.RegisterCode);
        var maintenance = scope.ServiceProvider.GetRequiredService<IOperationalRegisterAdminMaintenanceService>();
        Assert.Equal(1, await maintenance.FinalizeRegisterDirtyAsync(register));
        var reads = scope.ServiceProvider.GetRequiredService<IOperationalRegisterReadService>();
        var page = await reads.GetTurnoversPageAsync(new OperationalRegisterMonthlyProjectionPageRequest(
            register, CurrentMonth.AddMonths(-1), CurrentMonth.AddMonths(1)));
        Assert.Equal(expected, page.Lines.Sum(row => row.Values["hours"]));
    }

    private sealed class AuditFailure
    {
        public bool Triggered { get; set; }
        public bool SawMovement { get; set; }
    }

    private sealed class FailingAuditWriter(
        IAuditEventWriter inner,
        IOperationalRegisterReadService reads,
        AuditFailure failure) : IAuditEventWriter
    {
        public async Task WriteAsync(AuditEvent auditEvent, CancellationToken ct = default)
        {
            await inner.WriteAsync(auditEvent, ct);
            if (auditEvent.ActionCode == "document.post")
            {
                var page = await reads.GetMovementsPageAsync(new OperationalRegisterMovementsPageRequest(
                    OperationalRegisterId.FromCode(EquipmentUsageDefinitions.RegisterCode),
                    CurrentMonth.AddMonths(-1), CurrentMonth.AddMonths(1), DocumentId: auditEvent.EntityId), ct);
                failure.SawMovement = page.Lines.Count == 1;
                failure.Triggered = true;
                throw new InvalidOperationException("Injected audit failure after the document effects were written.");
            }
        }

        public async Task WriteBatchAsync(IReadOnlyList<AuditEvent> auditEvents, CancellationToken ct = default)
        {
            foreach (var auditEvent in auditEvents)
                await WriteAsync(auditEvent, ct);
        }
    }
}

using System.Data.Common;
using System.Net;
using System.Text.Json;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Hosting.Server;
using Microsoft.AspNetCore.Hosting.Server.Features;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using NGB.Hosting.AspNetCore.ErrorHandling;
using NGB.Tools.Exceptions;
using Xunit;

namespace EquipmentInspection.IntegrationTests;

public sealed class ErrorBoundaryContractTests
{
    private const string PrivateDetail = "Synthetic private provider diagnostics must stay server-side.";

    [Fact]
    public void Runtime_error_policy_preserves_control_flow_and_structured_errors_without_copying_private_messages()
    {
        using var cancellation = new CancellationTokenSource();
        cancellation.Cancel();
        var cancelled = new OperationCanceledException(cancellation.Token);
        var business = new NgbArgumentInvalidException("result", "Record a result.");
        var provider = new ProbeDatabaseException();
        Assert.Same(cancelled, NgbExceptionPolicy.Apply(cancelled, "example.read"));
        Assert.Same(business, NgbExceptionPolicy.Apply(business, "example.read"));
        Assert.Same(provider, NgbExceptionPolicy.Apply(provider, "example.read"));

        var unexpected = new InvalidOperationException(PrivateDetail);
        var wrapped = Assert.IsType<NgbUnexpectedException>(NgbExceptionPolicy.Apply(unexpected, "example.read"));
        Assert.Same(unexpected, wrapped.InnerException);
        Assert.Equal(NgbErrorKind.Infrastructure, wrapped.Kind);
        Assert.Equal("ngb.unexpected", wrapped.ErrorCode);
        Assert.Equal("example.read", wrapped.Context["operation"]);
        Assert.DoesNotContain(PrivateDetail, JsonSerializer.Serialize(wrapped.Context));
        Assert.DoesNotContain(PrivateDetail, wrapped.Message);

        var timeout = new TimeoutException(PrivateDetail);
        var timedOut = Assert.IsType<NgbTimeoutException>(NgbExceptionPolicy.Apply(timeout, "example.read"));
        Assert.Same(timeout, timedOut.InnerException);
        Assert.Equal("ngb.infra.timeout", timedOut.ErrorCode);
        Assert.DoesNotContain(PrivateDetail, JsonSerializer.Serialize(timedOut.Context));
        Assert.DoesNotContain(PrivateDetail, timedOut.Message);
    }

    [Fact]
    public async Task Production_http_boundary_maps_structured_failures_and_sanitizes_unexpected_provider_messages()
    {
        var failures = new (string Name, Exception Error, HttpStatusCode Status, string Code, string Kind)[]
        {
            ("required", new NgbArgumentRequiredException("equipment_id"),
                HttpStatusCode.BadRequest, "ngb.validation.required", "Validation"),
            ("invalid", new NgbArgumentInvalidException("result", "Record a result."),
                HttpStatusCode.BadRequest, "ngb.validation.invalid_argument", "Validation"),
            ("range", new NgbArgumentOutOfRangeException("hours", 25, "At most 24 hours."),
                HttpStatusCode.BadRequest, "ngb.validation.argument_out_of_range", "Validation"),
            ("missing", new MissingInspection(),
                HttpStatusCode.NotFound, "example.inspection.missing", "NotFound"),
            ("conflict", new InspectionConflict(),
                HttpStatusCode.Conflict, "example.inspection.conflict", "Conflict"),
            ("forbidden", new InspectionForbidden(),
                HttpStatusCode.Forbidden, "example.inspection.forbidden", "Forbidden"),
            ("configuration", new NgbConfigurationViolationException(PrivateDetail),
                HttpStatusCode.InternalServerError, "ngb.configuration.violation", "Configuration"),
            ("invariant", new NgbInvariantViolationException(PrivateDetail),
                HttpStatusCode.InternalServerError, "ngb.invariant.violation", "Infrastructure"),
            ("unexpected", new InvalidOperationException(PrivateDetail),
                HttpStatusCode.InternalServerError, "ngb.unexpected", "Unknown"),
            ("wrapped", NgbExceptionPolicy.Apply(new IOException(PrivateDetail), "example.read"),
                HttpStatusCode.InternalServerError, "ngb.unexpected", "Infrastructure"),
            ("timeout", NgbExceptionPolicy.Apply(new TimeoutException(PrivateDetail), "example.read"),
                HttpStatusCode.GatewayTimeout, "ngb.infra.timeout", "Infrastructure"),
            ("provider", new ProbeDatabaseException(),
                HttpStatusCode.ServiceUnavailable, "example.provider.unavailable", "Infrastructure"),
        };
        var builder = WebApplication.CreateBuilder(new WebApplicationOptions { EnvironmentName = Environments.Production });
        builder.WebHost.UseKestrel().UseUrls("http://127.0.0.1:0");
        builder.Logging.ClearProviders();
        builder.Services.AddGlobalErrorHandling();
        builder.Services.AddSingleton<INgbExceptionHttpMapper>(new ProbeMapper());
        await using var app = builder.Build();
        app.UseExceptionHandler();
        app.MapGet("/fault/{scenario}", (string scenario) => Task.FromException(failures.Single(item => item.Name == scenario).Error));
        await app.StartAsync();
        var addresses = app.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>()!;
        using var client = new HttpClient { BaseAddress = new Uri(Assert.Single(addresses.Addresses)) };

        foreach (var failure in failures)
        {
            using var response = await client.GetAsync("/fault/" + failure.Name);
            Assert.Equal(failure.Status, response.StatusCode);
            Assert.Equal("application/problem+json", response.Content.Headers.ContentType!.MediaType);
            var text = await response.Content.ReadAsStringAsync();
            Assert.DoesNotContain(PrivateDetail, text);
            using var json = JsonDocument.Parse(text);
            var body = json.RootElement;
            Assert.Equal((int)failure.Status, body.GetProperty("status").GetInt32());
            Assert.Equal("/fault/" + failure.Name, body.GetProperty("instance").GetString());
            Assert.False(string.IsNullOrWhiteSpace(body.GetProperty("traceId").GetString()));
            var error = body.GetProperty("error");
            Assert.Equal(failure.Code, error.GetProperty("code").GetString());
            Assert.Equal(failure.Kind, error.GetProperty("kind").GetString());
            if (failure.Name == "invalid")
                Assert.Equal("Record a result.", Assert.Single(error.GetProperty("errors").GetProperty("result").EnumerateArray()).GetString());
            if (failure.Name == "provider")
                Assert.Equal("probe", error.GetProperty("context").GetProperty("service").GetString());
        }
    }

    private sealed class MissingInspection()
        : NgbNotFoundException("Inspection was not found.", "example.inspection.missing");

    private sealed class InspectionConflict()
        : NgbConflictException("Reload the inspection.", "example.inspection.conflict");

    private sealed class InspectionForbidden()
        : NgbForbiddenException("Inspection access is denied.", "example.inspection.forbidden");

    private sealed class ProbeDatabaseException() : DbException(PrivateDetail);

    private sealed class ProbeMapper : INgbExceptionHttpMapper
    {
        public NgbExceptionHttpMapping? TryMap(Exception exception)
        {
            return exception is ProbeDatabaseException
                ? new NgbExceptionHttpMapping(StatusCodes.Status503ServiceUnavailable, "example.provider.unavailable",
                    NgbErrorKind.Infrastructure, new Dictionary<string, object?> { ["service"] = "probe" })
                : null;
        }
    }
}

using System.Net;
using System.Net.Http.Json;
using NGB.Contracts.Accounting;
using NGB.Contracts.Admin;
using NGB.Contracts.Reporting;
using NGB.Core.Documents.GeneralJournalEntry;
using NGB.Core.Reporting;
using Xunit;
using static EquipmentInspection.IntegrationTests.InspectionRequests;

namespace EquipmentInspection.IntegrationTests;

public sealed class FinancialStatementsHttpTests
{
    private static readonly string[] Reports =
    [
        AccountingReportCodes.BalanceSheet,
        AccountingReportCodes.IncomeStatement,
        AccountingReportCodes.CashFlowStatementIndirect,
        AccountingReportCodes.StatementOfChangesInEquity
    ];

    [Theory]
    [InlineData("administrator")]
    [InlineData("application-administrator")]
    public async Task Built_in_statements_reconcile_known_postings_and_preserve_inactive_account_history(string username)
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        if (username == "application-administrator")
        {
            await host.LinkUserAsync(username, true, InspectionHost.AdministratorRoleCode, "Statement reviewers");
        }
        using var admin = await host.CreateClientAsync(username);
        var cash = await SeedAsync(admin);
        var balance = await ExecuteAsync(admin, AccountingReportCodes.BalanceSheet);
        Assert.Equal(1170m, Amount(balance, "Total Assets"));
        Assert.Equal(50m, Amount(balance, "Total Liabilities"));
        Assert.Equal(1120m, Amount(balance, "Total Equity"));
        Assert.Equal(0m, Amount(balance, "Difference"));

        var income = await ExecuteAsync(admin, AccountingReportCodes.IncomeStatement);
        Assert.Equal(250m, Amount(income, "Total Income"));
        Assert.Equal(130m, Amount(income, "Total Expenses"));
        Assert.Equal(120m, Amount(income, "Net Income"));
        var equity = await ExecuteAsync(admin, AccountingReportCodes.StatementOfChangesInEquity);
        var totalEquity = Assert.Single(equity.Sheet.Rows, row => row.RowKind == ReportRowKind.Total);
        Assert.Equal(new[] { 0m, 1120m, 1120m }, totalEquity.Cells.Skip(1).Select(cell => cell.Value!.Value.GetDecimal()));
        var cashFlow = await ExecuteAsync(admin, AccountingReportCodes.CashFlowStatementIndirect);
        Assert.Equal(170m, Amount(cashFlow, "Net cash from operating activities"));
        Assert.Equal(0m, Amount(cashFlow, "Net cash from investing activities"));
        Assert.Equal(1000m, Amount(cashFlow, "Net cash from financing activities"));
        Assert.Equal(1170m, Amount(cashFlow, "Cash and cash equivalents at end of period"));

        using var inactive = await admin.PostAsync($"/api/chart-of-accounts/{cash.AccountId}/set-active?isActive=false", null);
        await EnsureSuccessAsync(inactive);
        var historicalBalance = await ExecuteAsync(admin, AccountingReportCodes.BalanceSheet);
        Assert.Equal(1170m, Amount(historicalBalance, "Total Assets"));
        var assets = Assert.Single(historicalBalance.Sheet.Rows,
            row => row.RowKind == ReportRowKind.Group && row.Cells[0].Display == "Assets");
        Assert.NotEmpty(assets.ChildrenPath!);
        var assetDetails = await PostAsync<ReportExecutionResponseDto>(admin,
            "/api/reports/" + AccountingReportCodes.BalanceSheet + "/execute",
            Request(AccountingReportCodes.BalanceSheet) with { GroupPath = assets.ChildrenPath });
        Assert.Contains(assetDetails.Sheet.Rows,
            row => row.RowKind == ReportRowKind.Detail && row.Cells[0].Display!.Contains(cash.Code, StringComparison.Ordinal));
        Assert.Equal(1170m, Amount(await ExecuteAsync(admin, AccountingReportCodes.CashFlowStatementIndirect),
            "Cash and cash equivalents at end of period"));
    }

    [Fact]
    public async Task Statement_metadata_dates_and_interactive_bounds_are_enforced()
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        using var admin = await host.CreateClientAsync("administrator");
        foreach (var code in Reports)
        {
            var definition = (await admin.GetFromJsonAsync<ReportDefinitionDto>("/api/report-definitions/" + code, Json))!;
            Assert.Equal(ReportExecutionMode.Canonical, definition.Mode);
            Assert.All(definition.Parameters!, parameter => Assert.True(parameter.IsRequired));
            var request = Request(code);
            var empty = await PostAsync<ReportExecutionResponseDto>(admin, "/api/reports/" + code + "/execute", request);
            Assert.False(empty.HasMore);
            Assert.Null(empty.NextCursor);
            Assert.InRange(empty.Sheet.Rows.Count, 0, definition.Capabilities!.MaxVisibleRows!.Value);
            foreach (var invalid in new[]
            {
                request with { Parameters = null },
                request with { DisablePaging = true },
                request with { Offset = 1 },
                request with { Cursor = "invalid-cursor" }
            })
            {
                using var response = await admin.PostAsJsonAsync("/api/reports/" + code + "/execute", invalid);
                Assert.True(response.StatusCode == HttpStatusCode.BadRequest,
                    $"{code}: expected HTTP 400, received {(int)response.StatusCode}.");
            }
        }
    }

    [Fact]
    public async Task Built_in_statements_require_current_report_permissions()
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        await host.LinkUserAsync("inactive-administrator", false, InspectionHost.AdministratorRoleCode, "Administrator");
        await host.LinkUserAsync("imitator", true, "inspection.statement-observer", "Administrator");
        foreach (var username in new[] { "reader", "inactive-administrator", "imitator" })
        {
            using var client = await host.CreateClientAsync(username);
            foreach (var code in Reports)
            {
                using var definition = await client.GetAsync("/api/report-definitions/" + code);
                using var execution = await client.PostAsJsonAsync("/api/reports/" + code + "/execute", Request(code));
                Assert.Equal(HttpStatusCode.Forbidden, definition.StatusCode);
                Assert.Equal(HttpStatusCode.Forbidden, execution.StatusCode);
            }
        }
        using var anonymous = host.CreateAnonymousClient();
        foreach (var code in Reports)
        {
            using var response = await anonymous.PostAsJsonAsync("/api/reports/" + code + "/execute", Request(code));
            Assert.Equal(HttpStatusCode.Unauthorized, response.StatusCode);
        }
    }

    private static ReportExecutionRequestDto Request(string code)
        => new(Parameters: code == AccountingReportCodes.BalanceSheet
            ? new Dictionary<string, string> { ["as_of_utc"] = "2026-05-31" }
            : new Dictionary<string, string> { ["from_utc"] = "2026-05-01", ["to_utc"] = "2026-05-31" });

    private static Task<ReportExecutionResponseDto> ExecuteAsync(HttpClient admin, string code)
        => PostAsync<ReportExecutionResponseDto>(admin, "/api/reports/" + code + "/execute", Request(code));

    private static decimal Amount(ReportExecutionResponseDto report, string label)
        => Assert.Single(report.Sheet.Rows, row => row.Cells[0].Display == label).Cells[^1].Value!.Value.GetDecimal();

    private static async Task<ChartOfAccountsAccountDto> SeedAsync(HttpClient admin)
    {
        var metadata = (await admin.GetFromJsonAsync<ChartOfAccountsMetadataDto>("/api/chart-of-accounts/metadata"))!;
        var financing = metadata.CashFlowLineOptions.First(line => line.AllowedRoles.Contains("FinancingCounterparty")).Value;
        var workingCapital = metadata.CashFlowLineOptions.First(line => line.AllowedRoles.Contains("WorkingCapital")).Value;
        var cash = await AccountAsync(admin, "statement.cash", "Statement cash", "Asset", "CashEquivalent");
        var equity = await AccountAsync(admin, "statement.equity", "Statement capital", "Equity", "FinancingCounterparty", financing);
        var income = await AccountAsync(admin, "statement.income", "Statement income", "Income");
        var expense = await AccountAsync(admin, "statement.expense", "Statement expense", "Expense");
        var payable = await AccountAsync(admin, "statement.payable", "Statement payable", "Liability", "WorkingCapital", workingCapital);
        await PostJournalAsync(admin, cash.AccountId, equity.AccountId, 1000m);
        await PostJournalAsync(admin, cash.AccountId, income.AccountId, 250m);
        await PostJournalAsync(admin, expense.AccountId, cash.AccountId, 80m);
        await PostJournalAsync(admin, expense.AccountId, payable.AccountId, 50m);
        return cash;
    }

    private static Task<ChartOfAccountsAccountDto> AccountAsync(
        HttpClient admin, string code, string name, string type, string? role = null, string? line = null)
        => PostAsync<ChartOfAccountsAccountDto>(admin, "/api/chart-of-accounts",
            new ChartOfAccountsUpsertRequestDto(code, name, type, CashFlowRole: role, CashFlowLineCode: line));

    private static async Task PostJournalAsync(HttpClient admin, Guid debit, Guid credit, decimal amount)
    {
        var draft = await PostAsync<GeneralJournalEntryDetailsDto>(admin, "/api/accounting/general-journal-entries",
            new CreateGeneralJournalEntryDraftRequestDto(new DateTime(2026, 5, 17, 12, 0, 0, DateTimeKind.Utc)));
        var path = "/api/accounting/general-journal-entries/" + draft.Document.Id;
        using var header = await admin.PutAsJsonAsync(path + "/header",
            new UpdateGeneralJournalEntryHeaderRequestDto("statement-fixture", ReasonCode: "STATEMENT", Memo: "Known statement totals"));
        await EnsureSuccessAsync(header);
        using var lines = await admin.PutAsJsonAsync(path + "/lines",
            new ReplaceGeneralJournalEntryLinesRequestDto("statement-fixture",
            [
                new((int)GeneralJournalEntryModels.LineSide.Debit, debit, amount, null),
                new((int)GeneralJournalEntryModels.LineSide.Credit, credit, amount, null)
            ]));
        await EnsureSuccessAsync(lines);
        foreach (var action in new[] { "submit", "approve", "post" })
        {
            using var response = await admin.PostAsync(path + "/" + action, null);
            await EnsureSuccessAsync(response);
        }
    }
}

