        var equipment = await SeedAsync(admin);
        var request = Request() with { Filters = Filter("equipment_id", new[] { equipment }) };
        var export = new ReportExportRequestDto(Parameters: request.Parameters, Filters: request.Filters);
        var path = "/api/reports/" + InspectionReports.Summary + "/export/xlsx";
        using var forbidden = await reader.PostAsJsonAsync(path, export);
        Assert.Equal(HttpStatusCode.Forbidden, forbidden.StatusCode);

        using var response = await admin.PostAsJsonAsync(path, export);
        await EnsureSuccessAsync(response);
        Assert.Equal("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            response.Content.Headers.ContentType!.MediaType);
        using var bytes = new MemoryStream(await response.Content.ReadAsByteArrayAsync());
        using var archive = new ZipArchive(bytes);
        using var sheet = archive.GetEntry("xl/worksheets/sheet1.xml")!.Open();
        var xml = XDocument.Load(sheet);
        XNamespace ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
        var rows = xml.Descendants(ns + "row").Select(row => row.Elements(ns + "c")
            .Select(cell => cell.Attribute("t")?.Value == "inlineStr"
                ? string.Concat(cell.Descendants(ns + "t").Select(text => text.Value))
                : cell.Element(ns + "v")?.Value ?? string.Empty)
            .ToArray()).ToArray();
        Assert.Contains(rows, row => row.SequenceEqual(["Follow-up", "1"]));
        Assert.Contains(rows, row => row.SequenceEqual(["Passed", "2"]));
        Assert.Contains(rows, row => row.Length == 2
            && row[0].Contains("Total", StringComparison.OrdinalIgnoreCase) && row[1] == "3");
        Assert.DoesNotContain(rows, row => row.Contains("Rejected"));
    }

    private static ReportExecutionRequestDto Request()
    {
        var today = DateOnly.FromDateTime(DateTime.UtcNow);
        return new ReportExecutionRequestDto(Parameters: new Dictionary<string, string>
        {
            ["from_utc"] = today.AddDays(-1).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture),
            ["to_utc"] = today.AddDays(1).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)
        });
    }

    private static Dictionary<string, ReportFilterValueDto> Filter(string field, object value)
        => new() { [field] = new ReportFilterValueDto(JsonSerializer.SerializeToElement(value)) };

    private static (string Result, decimal Count)[] Groups(IEnumerable<ReportSheetRowDto> rows)
        => rows.Where(row => row.RowKind == ReportRowKind.Group)
            .Select(row => (row.Cells[0].Display!, row.Cells[^1].Value!.Value.GetDecimal())).ToArray();

    private static decimal Total(IEnumerable<ReportSheetRowDto> rows)
        => rows.Single(row => row.RowKind == ReportRowKind.Total).Cells[^1].Value!.Value.GetDecimal();

    private static async Task<Guid> SeedAsync(HttpClient admin)
    {
        var first = await PostAsync<CatalogItemDto>(admin, "/api/catalogs/example.equipment", Payload(("display", "Bench A")));
        var second = await PostAsync<CatalogItemDto>(admin, "/api/catalogs/example.equipment", Payload(("display", "Bench B")));
        foreach (var (equipment, result) in new[]
        {
            (first.Id, "Passed"), (first.Id, "Passed"), (first.Id, "Follow-up"),
            (second.Id, "Passed"), (second.Id, "Rejected")
        })
        {
            var document = await PostAsync<DocumentDto>(admin, "/api/documents/example.inspection",
                CompleteInspectionPayload(equipment, result));
            var path = "/api/documents/example.inspection/" + document.Id;
            var state = await admin.GetFromJsonAsync<DocumentEditorStateDto>(path + "/editor-state", Json);
            using var posted = await ExecutePostAsync(admin, path, state!.DocumentVersion, document.Id.ToString());
            await EnsureSuccessAsync(posted);
        }

        await PostAsync<DocumentDto>(admin, "/api/documents/example.inspection",
            Payload(("equipment_id", first.Id), ("result", "Draft is not a completed inspection")));
        return first.Id;
    }
}

using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Serialization;
using NGB.Contracts.Common;
using NGB.Contracts.Documents;
using NGB.Contracts.Effects;
using NGB.Contracts.Services;
using Xunit;

namespace EquipmentInspection.IntegrationTests;

internal static class InspectionRequests
{
    internal static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web)
    {
        Converters = { new JsonStringEnumConverter() }
    };

    internal static RecordPayload Payload(params (string Name, object Value)[] fields)
    {
        return new RecordPayload(fields.ToDictionary(field => field.Name,
            field => JsonSerializer.SerializeToElement(field.Value)));
    }

    internal static RecordPayload CompleteInspectionPayload(Guid equipmentId, string result = "Passed")
    {
        return Payload(("equipment_id", equipmentId), ("result", result));
    }

    internal static async Task<T> PostAsync<T>(HttpClient client, string path, object payload)
    {
        using var response = await client.PostAsJsonAsync(path, payload);
        await EnsureSuccessAsync(response);
        return (await response.Content.ReadFromJsonAsync<T>(Json))!;
    }

    internal static Task<HttpResponseMessage> ExecutePostAsync(HttpClient client, string path, long version, string key)
        => ExecuteActionAsync(client, path, "post", version, key);

    internal static async Task<HttpResponseMessage> ExecuteActionAsync(
        HttpClient client, string path, string action, long version, string key)
    {
        using var request = new HttpRequestMessage(HttpMethod.Post, path + "/actions/" + action)
        {
            Content = JsonContent.Create(new ExecuteDocumentActionRequestDto(version))
        };
        request.Headers.Add("Idempotency-Key", key);
        return await client.SendAsync(request);
    }

    internal static async Task<ExecuteDocumentActionResultDto> ReadActionAsync(HttpResponseMessage response)
    {
        await EnsureSuccessAsync(response);
        return (await response.Content.ReadFromJsonAsync<ExecuteDocumentActionResultDto>(Json))!;
    }

    internal static async Task EnsureSuccessAsync(HttpResponseMessage response)
    {
        Assert.True(response.IsSuccessStatusCode,
            $"HTTP {(int)response.StatusCode}: {await response.Content.ReadAsStringAsync()}");
    }

    internal static async Task AssertErrorAsync(HttpResponseMessage response, HttpStatusCode status, string code)
    {
        Assert.Equal(status, response.StatusCode);
        var error = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal(code, error.GetProperty("error").GetProperty("code").GetString());
    }

    internal static async Task AssertEquivalentJsonAsync(HttpResponseMessage expected, HttpResponseMessage actual)
    {
        await EnsureSuccessAsync(expected);
        await EnsureSuccessAsync(actual);
        using var expectedJson = JsonDocument.Parse(await expected.Content.ReadAsByteArrayAsync());
        using var actualJson = JsonDocument.Parse(await actual.Content.ReadAsByteArrayAsync());
        Assert.True(JsonElement.DeepEquals(expectedJson.RootElement, actualJson.RootElement), "JSON response values differ.");
    }

    internal static async Task AssertNoEffectsAsync(HttpClient client, string path)
    {
        var effects = await client.GetFromJsonAsync<DocumentEffectsDto>(path + "/effects", Json);
        Assert.Empty(effects!.AccountingEntries);
        Assert.Empty(effects.OperationalRegisterMovements);
        Assert.Empty(effects.ReferenceRegisterWrites);
    }

    internal static async Task<(string Path, long Version)> CreateCompleteInspectionAsync(HttpClient client)
    {
        var equipment = await PostAsync<CatalogItemDto>(client, "/api/catalogs/example.equipment",
            Payload(("display", "Lifecycle inspection unit")));
        var draft = await PostAsync<DocumentDto>(client, "/api/documents/example.inspection",
            CompleteInspectionPayload(equipment.Id));
        var path = $"/api/documents/example.inspection/{draft.Id}";
        var state = await client.GetFromJsonAsync<DocumentEditorStateDto>(path + "/editor-state", Json);
        return (path, state!.DocumentVersion);
    }
}

