        await using var scope = host.Services.CreateAsyncScope();
        var services = scope.ServiceProvider;
        var registers = services.GetRequiredService<IReferenceRegisterRepository>();
        var fields = services.GetRequiredService<IReferenceRegisterFieldRepository>();
        var unitOfWork = services.GetRequiredService<IUnitOfWork>();
        var code = "example.reference-health-" + mode.ToString().ToLowerInvariant();
        var first = ReferenceRegisterId.FromCode(code);
        var second = ReferenceRegisterId.FromCode(code + "-second");

        // Seed metadata through public persistence ports to model an incomplete setup.
        // Normal management Upsert ensures physical tables immediately.
        await unitOfWork.ExecuteInUowTransactionAsync(async cancellation =>
        {
            foreach (var (id, registerCode) in new[] { (first, code), (second, code + "-second") })
            {
                await registers.UpsertAsync(new ReferenceRegisterUpsert(id, registerCode, "Reference health probe",
                    ReferenceRegisterPeriodicity.NonPeriodic, mode), DateTime.UtcNow, cancellation);
                await fields.ReplaceAsync(id,
                    [new ReferenceRegisterFieldDefinition("amount", "Amount", 1, ColumnType.Decimal, false)],
                    DateTime.UtcNow, cancellation);
            }
        });

        var endpoint = services.GetRequiredService<IReferenceRegisterAdminEndpoint>();
        var details = (await endpoint.GetDetailsByCodeAsync(code))!;
        Assert.Equal(first, details.Register.RegisterId);
        Assert.Equal(mode, details.Register.RecordMode);
        Assert.Equal("amount", Assert.Single(details.Fields).ColumnCode);
        Assert.Empty(details.DimensionRules);
        Assert.Contains(await endpoint.GetListAsync(), item => item.Register.RegisterId == first && item.FieldsCount == 1);
        Assert.False((await endpoint.GetPhysicalSchemaHealthByIdAsync(first))!.Records.Exists);
        Assert.False((await endpoint.GetPhysicalSchemaHealthByIdAsync(second))!.IsOk);
        var absent = Guid.CreateVersion7();
        Assert.Null(await endpoint.GetDetailsByIdAsync(absent));
        Assert.Null(await endpoint.GetPhysicalSchemaHealthByIdAsync(absent));
        Assert.Null(await endpoint.EnsurePhysicalSchemaByIdAsync(absent));

        var maintenance = services.GetRequiredService<IReferenceRegisterAdminMaintenanceService>();
        await maintenance.EnsurePhysicalSchemasByIdsAsync([first, first, Guid.Empty, absent]);
        var healthy = (await endpoint.GetPhysicalSchemaHealthByIdAsync(first))!;
        Assert.True(healthy.IsOk);
        Assert.Equal(ReferenceRegisterNaming.RecordsTable(code), healthy.Records.TableName);
        Assert.Empty(healthy.Records.MissingColumns);
        Assert.Empty(healthy.Records.MissingIndexes);
        Assert.True(healthy.Records.HasAppendOnlyGuard);
        Assert.False((await endpoint.GetPhysicalSchemaHealthByIdAsync(second))!.Records.Exists);
        Assert.True((await endpoint.EnsurePhysicalSchemaByIdAsync(first))!.IsOk);

        var all = await endpoint.EnsurePhysicalSchemaForAllAsync();
        Assert.Equal(all.TotalCount, all.OkCount);
        Assert.All(all.Items, item => Assert.True(item.IsOk));
        var repeated = await endpoint.GetPhysicalSchemaHealthReportAsync();
        Assert.Equal(all.TotalCount, repeated.TotalCount);
        Assert.Equal(all.OkCount, repeated.OkCount);
        Assert.False((await endpoint.GetDetailsByIdAsync(first))!.Register.HasRecords);
        Assert.False((await endpoint.GetDetailsByIdAsync(second))!.Register.HasRecords);
        await Assert.ThrowsAsync<NgbArgumentRequiredException>(() => endpoint.GetDetailsByCodeAsync(" "));
    }
}

using Dapper;
using Microsoft.Extensions.DependencyInjection;
using NGB.Metadata.Base;
using NGB.Persistence.ReferenceRegisters;
using NGB.Persistence.Schema;
using NGB.Persistence.UnitOfWork;
using NGB.PostgreSql.Bootstrap;
using NGB.PostgreSql.DependencyInjection;
using NGB.ReferenceRegisters;
using NGB.ReferenceRegisters.Contracts;
using NGB.Runtime.DependencyInjection;
using NGB.Runtime.UnitOfWork;
using Npgsql;
using Xunit;

namespace EquipmentInspection.IntegrationTests;

public sealed class ReferenceRegisterUpgradeTests
{
    private const string RegisterCode = "example.legacy-rates";
    private const string CancellationColumn = "__is_recorder_cancellation";
    private static readonly DateTime OriginalDate = new(2026, 10, 20, 12, 0, 0, DateTimeKind.Utc);
    private static readonly DateTime EarlierDate = new(2026, 9, 27, 12, 0, 0, DateTimeKind.Utc);

    [Theory]
    [InlineData(ReferenceRegisterPeriodicity.Month, false)]
    [InlineData(ReferenceRegisterPeriodicity.Day, false)]
    [InlineData(ReferenceRegisterPeriodicity.Month, true)]
    [InlineData(ReferenceRegisterPeriodicity.NonPeriodic, false)]
    public async Task Migrator_preserves_legacy_rows_and_new_cancellations_do_not_hide_a_backdated_replacement(
        ReferenceRegisterPeriodicity periodicity, bool legacyDeletion)
    {
        var registerId = ReferenceRegisterId.FromCode(RegisterCode);
        var table = ReferenceRegisterNaming.RecordsTable(RegisterCode);
        var recorder = Guid.CreateVersion7();
        string? originalJson = null;
        await using var host = new InspectionHost(prepareDatabase: async connectionString =>
        {
            await CreateLegacySchemaAsync(connectionString, registerId, table, recorder, periodicity, legacyDeletion);
            await using var connection = new NpgsqlConnection(connectionString);
            Assert.False(await HasCancellationColumnAsync(connection, table));
            originalJson = await connection.QuerySingleAsync<string>($"SELECT row_to_json(r)::text FROM {table} r;");
        });
        // InspectionHost invokes the actual application Migrator twice before starting the API.
        await host.StartAsync();
        await using var verification = new NpgsqlConnection(host.ConnectionString);
        var periodic = periodicity != ReferenceRegisterPeriodicity.NonPeriodic;
        Assert.Equal(periodic, await HasCancellationColumnAsync(verification, table));
        Assert.Equal(originalJson, await verification.QuerySingleAsync<string>($"""
            SELECT row_to_json(r)::text FROM (
                SELECT record_id, dimension_set_id, period_utc, period_bucket_utc,
                       recorder_document_id, recorded_at_utc, is_deleted, amount
                FROM {table}
            ) r;
            """));
        if (periodic)
        {
            Assert.False(await verification.QuerySingleAsync<bool>($"SELECT {CancellationColumn} FROM {table};"));
        }

        await using var scope = host.Services.CreateAsyncScope();
        var services = scope.ServiceProvider;
        var records = services.GetRequiredService<IReferenceRegisterRecordsReader>();
        var store = services.GetRequiredService<IReferenceRegisterRecordsStore>();
        var cancellations = Assert.IsAssignableFrom<IReferenceRegisterRecorderTombstoneWriter>(store);
        var uow = services.GetRequiredService<IUnitOfWork>();
        var original = Assert.Single(await records.ListByRecorderDocumentAsync(registerId, recorder));
        Assert.Equal(legacyDeletion, original.IsDeleted);
        Assert.Equal(1000m, original.Values["amount"]);
        Assert.Single(original.Values);
        var current = await records.SliceLastAsync(registerId, Guid.Empty, DateTime.UtcNow, recorder);
        Assert.Equal(legacyDeletion, current!.IsDeleted);

        foreach (var (date, amount) in new[] { (OriginalDate, 900m), (EarlierDate, 1400m) })
        {
            await uow.ExecuteInUowTransactionAsync(async ct =>
            {
                await cancellations.AppendTombstonesForRecorderAsync(registerId, recorder, null, ct);
            });
            var cancelled = await records.SliceLastAsync(registerId, Guid.Empty, DateTime.UtcNow, recorder);
            Assert.True(cancelled is null || cancelled.IsDeleted);
            await uow.ExecuteInUowTransactionAsync(async ct =>
            {
                await store.AppendAsync(registerId,
                    [new ReferenceRegisterRecordWrite(Guid.Empty, periodic ? date : null, recorder,
                        new Dictionary<string, object?> { ["amount"] = amount })], ct);
            });
            var active = await records.SliceLastAsync(registerId, Guid.Empty, DateTime.UtcNow, recorder);
            Assert.NotNull(active);
            Assert.Equal(amount, active.Values["amount"]);
            Assert.Single(active.Values);
            if (periodic)
            {
                foreach (var effective in new[] { date, OriginalDate, OriginalDate.AddMonths(1) })
                {
                    var slice = await records.SliceLastForEffectiveMomentAsync(registerId, Guid.Empty,
                        effective, DateTime.UtcNow, recorder);
                    Assert.Equal(active.RecordId, slice!.RecordId);
                }
                var beforeEffectiveDate = await records.SliceLastForEffectiveMomentAsync(registerId, Guid.Empty,
                    date.AddTicks(-10), DateTime.UtcNow, recorder);
                Assert.True(beforeEffectiveDate is null || beforeEffectiveDate.IsDeleted);
            }
        }

        var history = await records.ListByRecorderDocumentAsync(registerId, recorder);
        var retained = Assert.Single(history, row => row.RecordId == original.RecordId);
        Assert.Equal(original.RecordedAtUtc, retained.RecordedAtUtc);
        Assert.Equal(original.PeriodUtc, retained.PeriodUtc);
        Assert.Equal(original.IsDeleted, retained.IsDeleted);
        Assert.Equal(original.Values["amount"], retained.Values["amount"]);
        var asOriginallyKnown = periodic
            ? await records.SliceLastForEffectiveMomentAsync(registerId, Guid.Empty, OriginalDate, original.RecordedAtUtc, recorder)
            : await records.SliceLastAsync(registerId, Guid.Empty, original.RecordedAtUtc, recorder);
        if (legacyDeletion)
        {
            Assert.True(asOriginallyKnown!.IsDeleted);
        }
        else
        {
            Assert.Equal(original.RecordId, asOriginallyKnown!.RecordId);
        }

        var beforeRepeat = (await verification.QueryAsync<string>($"SELECT row_to_json(r)::text FROM {table} r ORDER BY record_id;")).ToArray();
        Assert.Equal(0, await Migrator.Program.Main(["--connection=" + host.ConnectionString]));
        Assert.Equal(beforeRepeat, await verification.QueryAsync<string>($"SELECT row_to_json(r)::text FROM {table} r ORDER BY record_id;"));
    }

    private static async Task CreateLegacySchemaAsync(string connectionString, Guid registerId, string table,
        Guid recorder, ReferenceRegisterPeriodicity periodicity, bool legacyDeletion)
    {
        await using var connection = new NpgsqlConnection(connectionString);
        await connection.OpenAsync();
        // Replay the packaged migration prefix, retaining real checksums. Do not fake
        // an applied migration or enable OutOfOrder to manufacture an upgrade result.
        var evolve = new EvolveDb.Evolve(connection)
        {
            IsEraseDisabled = true,
            Schemas = ["public"],
            MetadataTableName = "migration_changelog__platform",
            TargetVersion = new EvolveDb.Migration.MigrationVersion("2026_11_08_0100"),
            EmbeddedResourceAssemblies = [typeof(DatabaseBootstrapper).Assembly],
            EmbeddedResourceFilters = ["NGB.PostgreSql.db.migrations.V"]
        };
        evolve.Migrate();

        var registrations = new ServiceCollection();
        registrations.AddLogging();
        registrations.AddNgbRuntime().AddNgbPostgres(connectionString);
        await using var provider = registrations.BuildServiceProvider();
        await using var scope = provider.CreateAsyncScope();
        var services = scope.ServiceProvider;
        var uow = services.GetRequiredService<IUnitOfWork>();
        await uow.ExecuteInUowTransactionAsync(async ct =>
        {
            await services.GetRequiredService<IReferenceRegisterRepository>().UpsertAsync(
                new ReferenceRegisterUpsert(registerId, RegisterCode, "Legacy application rates", periodicity,
                    ReferenceRegisterRecordMode.SubordinateToRecorder), DateTime.UtcNow, ct);
            await services.GetRequiredService<IReferenceRegisterFieldRepository>().ReplaceAsync(registerId,
                [new ReferenceRegisterFieldDefinition("amount", "Amount", 1, ColumnType.Decimal, false)], DateTime.UtcNow, ct);
            // Fixture-only legacy layout and history, belonging to an application unknown to the migrator.
            await uow.Connection.ExecuteAsync(new CommandDefinition($"""
                INSERT INTO documents (id, type_code, date_utc, status)
                VALUES (@Recorder, 'example.legacy-rate-document', @Date, 1);
                CREATE TABLE {table} (
                    record_id bigserial PRIMARY KEY,
                    dimension_set_id uuid NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000'
                        REFERENCES platform_dimension_sets(dimension_set_id),
                    period_utc timestamptz,
                    period_bucket_utc timestamptz,
                    recorder_document_id uuid REFERENCES documents(id),
                    recorded_at_utc timestamptz NOT NULL DEFAULT now(),
                    is_deleted boolean NOT NULL DEFAULT false,
                    amount numeric(28, 8) NOT NULL
                );
                INSERT INTO {table} (period_utc, period_bucket_utc, recorder_document_id, is_deleted, amount)
                VALUES (@Period, @Bucket, @Recorder, @Deleted, 1000);
                UPDATE reference_registers SET has_records = true WHERE register_id = @Register;
                """, new
            {
                Recorder = recorder,
                Date = OriginalDate,
                Period = periodicity == ReferenceRegisterPeriodicity.NonPeriodic ? (DateTime?)null : OriginalDate,
                Bucket = ReferenceRegisterPeriodBucket.ComputeUtc(
                    periodicity == ReferenceRegisterPeriodicity.NonPeriodic ? null : OriginalDate, periodicity),
                Deleted = legacyDeletion,
                Register = registerId
            }, transaction: uow.Transaction, cancellationToken: ct));
        });
    }

    private static Task<bool> HasCancellationColumnAsync(NpgsqlConnection connection, string table)
        => connection.QuerySingleAsync<bool>("""
            SELECT EXISTS (
                SELECT 1 FROM information_schema.columns
                WHERE table_schema = 'public' AND table_name = @Table AND column_name = @Column
            );
            """, new { Table = table, Column = CancellationColumn });
}

using System.Globalization;
using System.IO.Compression;
using System.Net;
using System.Net.Http.Json;
using System.Security.Cryptography;
using EquipmentInspection.Definitions;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Options;
using NGB.Api.Reporting;
using NGB.Application.Abstractions.Services;
using NGB.Contracts.Reporting;
using NGB.Runtime.Reporting;
using Xunit;
using static EquipmentInspection.IntegrationTests.InspectionRequests;

namespace EquipmentInspection.IntegrationTests;

public sealed class ReportAdmissionTests
{
    [Fact]
    public async Task Page_and_download_capacity_are_independent_and_recover_after_busy_responses()
    {
        var key = Convert.ToBase64String(RandomNumberGenerator.GetBytes(32));
        await using var host = new InspectionHost(configuration: new Dictionary<string, string>
        {
            ["Reporting:Requests:ConcurrentPages"] = "1",
            ["Reporting:Requests:QueuedPages"] = "0",
            ["Reporting:Requests:ConcurrentDownloads"] = "1",
            ["Reporting:Requests:QueuedDownloads"] = "0",
            ["Reporting:Requests:PageTimeoutSeconds"] = "17",
            ["Reporting:Requests:DownloadTimeoutSeconds"] = "23",
            ["Reporting:Cursor:SigningKey"] = key
        });
        await host.StartAsync();
        using var admin = await host.CreateClientAsync("administrator");
        var budget = host.Services.GetRequiredService<ReportRequestBudget>();
        var admission = host.Services.GetRequiredService<IReportRequestAdmission>();
        Assert.Same(budget, admission);
        Assert.Equal(TimeSpan.FromSeconds(17), admission.ExecutionTimeout);
        Assert.Equal(TimeSpan.FromSeconds(23), budget.Timeout(download: true));

        var request = Request();
        var path = "/api/reports/" + InspectionReports.Summary;
        var export = new ReportExportRequestDto(Parameters: request.Parameters);
        using (var page = await admission.AcquireAsync(CancellationToken.None))
        {
            Assert.NotNull(page);
            using var busy = await admin.PostAsJsonAsync(path + "/execute", request);
            Assert.Equal(HttpStatusCode.TooManyRequests, busy.StatusCode);
            Assert.Equal(TimeSpan.FromSeconds(3), busy.Headers.RetryAfter!.Delta);
            using var download = await admin.PostAsJsonAsync(path + "/export/xlsx", export);
            await AssertWorkbookAsync(download);
        }

        using (var download = await budget.AcquireAsync(download: true, CancellationToken.None))
        {
            Assert.NotNull(download);
            Assert.True(download.IsAcquired);
            using var busy = await admin.PostAsJsonAsync(path + "/export/xlsx", export);
            Assert.Equal(HttpStatusCode.TooManyRequests, busy.StatusCode);
            Assert.Equal(TimeSpan.FromSeconds(3), busy.Headers.RetryAfter!.Delta);
            var page = await PostAsync<ReportExecutionResponseDto>(admin, path + "/execute", request);
            Assert.False(page.HasMore);
        }

        await PostAsync<ReportExecutionResponseDto>(admin, path + "/execute", request);
        using var recovered = await admin.PostAsJsonAsync(path + "/export/xlsx", export);
        await AssertWorkbookAsync(recovered);
        Assert.Equal(1, budget.Statistics(download: false).CurrentAvailablePermits);
        Assert.Equal(1, budget.Statistics(download: true).CurrentAvailablePermits);
        Assert.Equal(0, budget.Statistics(download: false).CurrentQueuedCount);
        Assert.Equal(0, budget.Statistics(download: true).CurrentQueuedCount);

        using var replica = new ReportCursorProtector(Options.Create(new ReportCursorProtectionOptions { SigningKey = key }));
        using var other = new ReportCursorProtector(Options.Create(new ReportCursorProtectionOptions
        {
            SigningKey = Convert.ToBase64String(RandomNumberGenerator.GetBytes(32))
        }));
        var cursor = host.Services.GetRequiredService<ReportCursorProtector>().Protect("replica continuation probe");
        Assert.Equal("replica continuation probe", replica.Unprotect(cursor));
        Assert.Throws<CryptographicException>(() => other.Unprotect(cursor));
    }

    [Fact]
    public async Task Cancelling_a_queued_report_releases_its_queue_slot_without_releasing_the_active_lease()
    {
        using var budget = new ReportRequestBudget(Options.Create(new ReportRequestLimits
        {
            ConcurrentPages = 1,
            QueuedPages = 1,
            PageQueueTimeoutSeconds = 30
        }));
        var admission = (IReportRequestAdmission)budget;
        using (var active = await admission.AcquireAsync(CancellationToken.None))
        {
            Assert.NotNull(active);
            using var cancelled = new CancellationTokenSource();
            var waiting = admission.AcquireAsync(cancelled.Token).AsTask();
            Assert.False(waiting.IsCompleted);
            Assert.Equal(1, budget.Statistics(download: false).CurrentQueuedCount);
            await cancelled.CancelAsync();
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() => waiting);
            Assert.Equal(0, budget.Statistics(download: false).CurrentQueuedCount);
            Assert.Equal(0, budget.Statistics(download: false).CurrentAvailablePermits);
        }

        using var recovered = await admission.AcquireAsync(CancellationToken.None);
        Assert.NotNull(recovered);
    }

    private static ReportExecutionRequestDto Request()
    {
        var today = DateOnly.FromDateTime(DateTime.UtcNow);
        return new ReportExecutionRequestDto(Parameters: new Dictionary<string, string>
        {
            ["from_utc"] = today.AddDays(-1).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture),
            ["to_utc"] = today.AddDays(1).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)
        });
    }

    private static async Task AssertWorkbookAsync(HttpResponseMessage response)
    {
        await EnsureSuccessAsync(response);
        using var content = new MemoryStream(await response.Content.ReadAsByteArrayAsync());
        using var archive = new ZipArchive(content, ZipArchiveMode.Read);
        Assert.NotNull(archive.GetEntry("xl/worksheets/sheet1.xml"));
    }
}

using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using EquipmentInspection.Definitions;
using EquipmentInspection.Runtime;
