using static EquipmentInspection.IntegrationTests.InspectionRequests;

namespace EquipmentInspection.IntegrationTests;

public sealed class SearchHttpTests
{
    private const string Path = "/api/equipment-search";

    [Theory]
    [InlineData("administrator")]
    [InlineData("application-administrator")]
    public async Task Both_administrators_search_installed_definitions_with_canonical_filters(string username)
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        if (username == "application-administrator")
        {
            await host.LinkUserAsync(username, true, InspectionHost.AdministratorRoleCode, "Search owners");
        }

        using var admin = await host.CreateClientAsync(username);
        var equipment = await PostAsync<CatalogItemDto>(admin, "/api/catalogs/example.equipment",
            Payload(("display", "Inspection")));
        var document = await PostAsync<DocumentDto>(admin, "/api/documents/example.inspection",
            Payload(("display", "Inspection search unit"), ("equipment_id", equipment.Id), ("result", "Passed")));
        var catalog = await SearchAsync(admin, "Inspection", "&kind=Catalog&typeCode=example.equipment");
        Assert.Equal(equipment.Id, Assert.Single(catalog.Items).Id);
        Assert.False(catalog.Truncated);
        Assert.Empty(catalog.UnavailableSources);
        var documents = await SearchAsync(admin, "Inspection", "&kind=Document&typeCode=example.inspection");
        var documentHit = Assert.Single(documents.Items);
        Assert.Equal(document.Id, documentHit.Id);
        Assert.Equal("document", documentHit.Kind);
        Assert.False(documents.Truncated);
        Assert.Empty(documents.UnavailableSources);
        var documentScope = await SearchAsync(admin, "Inspection", "&kind=Document");
        Assert.Equal(document.Id, Assert.Single(documentScope.Items).Id);
        var reports = await SearchAsync(admin, "Inspection", "&kind=Report&typeCode=example.inspection-summary");
        var reportHit = Assert.Single(reports.Items);
        Assert.Equal("example.inspection-summary", reportHit.TypeCode);
        Assert.Equal("report", reportHit.Kind);
        Assert.Null(reportHit.Id);
        foreach (var typeCode in new[] { "example.unknown", "EXAMPLE.EQUIPMENT" })
        {
            Assert.Empty((await SearchAsync(admin, "Inspection", "&kind=Catalog&typeCode=" + typeCode)).Items);
        }
    }

    [Fact]
    public async Task Search_bounds_results_and_omits_deleted_catalog_records()
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        using var admin = await host.CreateClientAsync("administrator");
        var ids = new List<Guid>();
        for (var index = 0; index < 7; index++)
        {
            var item = await PostAsync<CatalogItemDto>(admin, "/api/catalogs/example.equipment",
                Payload(("display", $"Bounded search {index}")));
            ids.Add(item.Id);
        }

        var bounded = await SearchAsync(admin, "Bounded search", "&kind=Catalog&limit=2");
        Assert.Equal(2, bounded.Items.Count);
        Assert.True(bounded.Truncated);
        Assert.Empty(bounded.UnavailableSources);
        var perType = await SearchAsync(admin, "Bounded search", "&kind=Catalog&limit=50");
        Assert.Equal(6, perType.Items.Count);
        Assert.True(perType.Truncated);
        Assert.All(perType.Items, item => Assert.Contains(item.Id!.Value, ids));
        foreach (var id in ids.Take(2))
        {
            using var deleted = await admin.PostAsync($"/api/catalogs/example.equipment/{id}/mark-for-deletion", null);
            await EnsureSuccessAsync(deleted);
        }

        var remaining = await SearchAsync(admin, "Bounded search", "&kind=Catalog&limit=50");
        Assert.Equal(5, remaining.Items.Count);
        Assert.False(remaining.Truncated);
        Assert.Equal(ids.Skip(2).Order(), remaining.Items.Select(item => item.Id!.Value).Order());
    }

    [Fact]
    public async Task Invalid_search_requests_are_rejected_at_the_public_boundary()
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        using var admin = await host.CreateClientAsync("administrator");
        foreach (var suffix in new[]
        {
            "?query=%20", "?query=" + new string('a', 257), "?query=Inspection&limit=0",
            "?query=Inspection&limit=51", "?query=Inspection&kind=99", "?query=Inspection&kind=unknown",
            "?query=Inspection&typeCode=" + new string('a', 129)
        })
        {
            using var response = await admin.GetAsync(Path + suffix);
            Assert.True(response.StatusCode == HttpStatusCode.BadRequest,
                $"Expected HTTP 400 for {suffix}; received {(int)response.StatusCode}.");
        }

        Assert.Empty((await SearchAsync(admin, new string('a', 256), "&limit=50")).Items);
        var withoutType = await SearchAsync(admin, "Inspection", "&kind=Report");
        var blankType = await SearchAsync(admin, "Inspection", "&kind=Report&typeCode=%20");
        Assert.Contains(withoutType.Items, item => item.TypeCode == InspectionReports.Summary);
        Assert.Contains(withoutType.Items, item => item.TypeCode == InspectionReports.OutcomeRate);
        Assert.Equal(withoutType.Items.ToArray(), blankType.Items.ToArray());
        Assert.All(blankType.Items, item => Assert.Equal("report", item.Kind));
    }

    [Fact]
    public async Task Current_search_permissions_follow_role_changes_and_block_inactive_accounts()
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        await host.LinkUserAsync("reader", true, "inspection.search-reader", "Search reader");
        await host.LinkUserAsync("inactive-administrator", false, InspectionHost.AdministratorRoleCode, "Administrator");
        await host.LinkUserAsync("imitator", true, "inspection.search-observer", "Administrator");
        using var admin = await host.CreateClientAsync("administrator");
        var equipment = await PostAsync<CatalogItemDto>(admin, "/api/catalogs/example.equipment",
            Payload(("display", "Inspection search access")));
        using var reader = await host.CreateClientAsync("reader");
        Assert.Empty((await SearchAsync(reader, "Inspection")).Items);
        var access = (await reader.GetFromJsonAsync<CurrentAccessDto>("/api/security/me/access"))!;
        var role = await PostAsync<RoleDetailsDto>(admin, "/api/security/roles",
            new CreateRoleRequestDto("inspection.equipment-search", "Equipment search", null,
                [new PermissionAssignmentDto("catalog", "example.equipment", "view")]));
        using var assign = await admin.PutAsJsonAsync($"/api/security/users/{access.UserId}/roles",
            new ReplaceUserRolesRequestDto([role.RoleId]));
        await EnsureSuccessAsync(assign);
        Assert.Empty((await SearchAsync(reader, "Inspection")).Items);
        using var lookup = await admin.PutAsJsonAsync($"/api/security/roles/{role.RoleId}/permissions",
            new ReplaceRolePermissionsRequestDto([
                new PermissionAssignmentDto("catalog", "example.equipment", "view"),
                new PermissionAssignmentDto("catalog", "example.equipment", "lookup")
            ]));
        await EnsureSuccessAsync(lookup);
        Assert.Equal(equipment.Id, Assert.Single((await SearchAsync(reader, "Inspection")).Items).Id);
        using var revoke = await admin.PutAsJsonAsync($"/api/security/roles/{role.RoleId}/permissions",
            new ReplaceRolePermissionsRequestDto([]));
        await EnsureSuccessAsync(revoke);
        Assert.Empty((await SearchAsync(reader, "Inspection")).Items);
        foreach (var username in new[] { "inactive-administrator", "imitator" })
        {
            using var denied = await host.CreateClientAsync(username);
            Assert.Empty((await SearchAsync(denied, "Inspection")).Items);
        }
        using var anonymous = host.CreateAnonymousClient();
        using var response = await anonymous.GetAsync(Path + "?query=Inspection");
        Assert.Equal(HttpStatusCode.Unauthorized, response.StatusCode);
    }

    [Fact]
    public async Task A_failed_search_source_is_explicit_and_preserves_other_authorized_results()
    {
        await using var host = new InspectionHost(configureServices: services =>
            services.Replace(ServiceDescriptor.Scoped<IAuthorizedReportReadService, UnavailableReports>()));
        await host.StartAsync();
        using var admin = await host.CreateClientAsync("administrator");
        var equipment = await PostAsync<CatalogItemDto>(admin, "/api/catalogs/example.equipment",
            Payload(("display", "Inspection available equipment")));
        var result = await SearchAsync(admin, "Inspection");
        Assert.Equal(equipment.Id, Assert.Single(result.Items).Id);
        Assert.True(result.Truncated);
        Assert.Equal(new[] { "reports" }, result.UnavailableSources);
        var catalog = await SearchAsync(admin, "Inspection", "&kind=Catalog");
        Assert.Equal(equipment.Id, Assert.Single(catalog.Items).Id);
        Assert.False(catalog.Truncated);
        Assert.Empty(catalog.UnavailableSources);
    }

    [Fact]
    public async Task General_journal_search_uses_specialized_reads_without_disabling_other_documents()
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        using var admin = await host.CreateClientAsync("administrator");
        var journal = await PostAsync<GeneralJournalEntryDetailsDto>(admin, "/api/accounting/general-journal-entries",
            new CreateGeneralJournalEntryDraftRequestDto(new DateTime(2026, 5, 17, 12, 0, 0, DateTimeKind.Utc)));
        var inspection = await PostAsync<DocumentDto>(admin, "/api/documents/example.inspection",
            Payload(("display", "Inspection alongside journal")));
        var scoped = await SearchAsync(admin, journal.Document.Number!, "&kind=GeneralJournalEntry");
        var hit = Assert.Single(scoped.Items);
        Assert.Equal(journal.Document.Id, hit.Id);
        Assert.Equal("generalJournalEntry", hit.Kind);
        Assert.Equal(journal.Document.Number, hit.Title);
        Assert.False(scoped.Truncated);
        Assert.Empty(scoped.UnavailableSources);
        var unscoped = await SearchAsync(admin, journal.Document.Number!);
        Assert.Contains(unscoped.Items, item => item.Id == journal.Document.Id);
        Assert.Empty(unscoped.UnavailableSources);
        var all = await SearchAsync(admin, "Inspection");
        Assert.False(all.Truncated);
        Assert.Empty(all.UnavailableSources);
        Assert.Contains(all.Items, item => item.Kind == "report");
        Assert.Contains(all.Items, item => item.Id == inspection.Id && item.Kind == "document");

        await using var scope = host.Services.CreateAsyncScope();
        var documents = scope.ServiceProvider.GetRequiredService<IDocumentService>();
        var error = await Assert.ThrowsAsync<NgbConfigurationViolationException>(() =>
            documents.LookupAcrossTypesAsync([AccountingDocumentTypeCodes.GeneralJournalEntry],
                journal.Document.Number, 6, false, CancellationToken.None));
        Assert.Contains("must define a display column", error.Message);
        Assert.Contains(AccountingDocumentTypeCodes.GeneralJournalEntry, error.Message);
        var typed = (await admin.GetFromJsonAsync<GeneralJournalEntryDetailsDto>(
            "/api/accounting/general-journal-entries/" + journal.Document.Id, Json))!;
        Assert.Equal(journal.Document.Id, typed.Document.Id);
    }

    private static async Task<NgbSearchResult> SearchAsync(HttpClient client, string query, string suffix = "")
    {
        using var response = await client.GetAsync(Path + "?query=" + Uri.EscapeDataString(query) + suffix);
        await EnsureSuccessAsync(response);
        return (await response.Content.ReadFromJsonAsync<NgbSearchResult>(Json))!;
    }

    private sealed class UnavailableReports : IAuthorizedReportReadService
    {
        public Task<IReadOnlyList<ReportDefinitionDto>> GetAllDefinitionsAsync(CancellationToken ct)
            => throw new IOException("Private provider details must not enter search results.");

        public Task<ReportDefinitionDto> GetDefinitionAsync(string reportCode, CancellationToken ct)
            => throw new InvalidOperationException("Search must only discover report definitions.");

        public Task<ReportExecutionResponseDto> ExecuteAsync(
            string reportCode, ReportExecutionRequestDto request, CancellationToken ct)
            => throw new InvalidOperationException("Search must not execute reports.");
    }
}

using Microsoft.Extensions.Logging.Abstractions;
using NGB.Api.Search;
using NGB.Runtime.Search;
using Xunit;

namespace EquipmentInspection.IntegrationTests;

public sealed class SearchPipelineContractTests
{
    [Fact]
    public async Task Custom_search_profiles_run_sources_sequentially_and_report_partial_availability()
    {
        var calls = new List<string>();
        var active = 0;
        var result = await NgbSearchPipeline.ExecuteAsync(
            " inspection ", 50, NgbSearchScope.All, 8,
            async (query, limit, ct) =>
            {
                Assert.Equal("inspection", query);
                Assert.Equal(8, limit);
                Assert.Equal(0, active++);
                calls.Add("documents");
                await Task.Yield();
                active--;
                return "document results";
            },
            (query, limit, ct) =>
            {
                Assert.Equal(0, active);
                calls.Add("catalogs");
                throw new IOException("Private connection details.");
            },
            (query, limit, ct) =>
            {
                Assert.Equal(0, active);
                calls.Add("reports");
                return Task.FromResult<string?>("report results");
            },
            NullLogger.Instance, CancellationToken.None);

        Assert.Equal(new[] { "documents", "catalogs", "reports" }, calls);
        Assert.Equal(new[] { "document results", "report results" }, result.Groups);
        Assert.Equal(new[] { "catalogs" }, result.UnavailableSources);
    }

    [Fact]
    public async Task Selected_search_scope_skips_other_sources_and_preserves_cancellation()
    {
        using var cancellation = new CancellationTokenSource();
        var invoked = false;
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => NgbSearchPipeline.ExecuteAsync<string>(
            "inspection", 0, NgbSearchScope.Catalogs, 50,
            (query, limit, ct) => throw new InvalidOperationException("Document scope must not run."),
            async (query, limit, ct) =>
            {
                invoked = true;
                Assert.Equal(20, limit);
                Assert.Equal(cancellation.Token, ct);
                await cancellation.CancelAsync();
                ct.ThrowIfCancellationRequested();
                return null;
            },
            (query, limit, ct) => throw new InvalidOperationException("Report scope must not run."),
            NullLogger.Instance, cancellation.Token));
        Assert.True(invoked);
    }

    [Theory]
    [InlineData(null, NgbSearchScope.All)]
    [InlineData("", NgbSearchScope.All)]
    [InlineData(":", NgbSearchScope.Documents)]
    [InlineData(" Documents ", NgbSearchScope.Documents)]
    [InlineData("@", NgbSearchScope.Catalogs)]
    [InlineData("Catalog", NgbSearchScope.Catalogs)]
    [InlineData("#", NgbSearchScope.Reports)]
    [InlineData("Reports", NgbSearchScope.Reports)]
    [InlineData("unknown", NgbSearchScope.None)]
    public async Task Command_palette_scopes_keep_unknown_syntax_out_of_business_readers(
        string? input, NgbSearchScope expected)
    {
        var scope = CommandPaletteSearchScope.Parse(input);
        Assert.Equal(expected, scope);
        var result = await NgbSearchPipeline.ExecuteAsync(
            "inspection", 20, scope, 50,
            (query, limit, ct) => Task.FromResult<string?>("documents"),
            (query, limit, ct) => Task.FromResult<string?>("catalogs"),
            (query, limit, ct) => Task.FromResult<string?>("reports"),
            NullLogger.Instance, CancellationToken.None);
        var expectedGroups = expected switch
        {
            NgbSearchScope.All => new[] { "documents", "catalogs", "reports" },
            NgbSearchScope.Documents => ["documents"],
            NgbSearchScope.Catalogs => ["catalogs"],
            NgbSearchScope.Reports => ["reports"],
            _ => []
        };
        Assert.Equal(expectedGroups, result.Groups);
        Assert.Empty(result.UnavailableSources);
    }
}

using System.Net;
using System.Net.Http.Json;
using NGB.Contracts.Audit;
using NGB.Contracts.Common;
using NGB.Contracts.Security;
using Xunit;
using static EquipmentInspection.IntegrationTests.InspectionRequests;

namespace EquipmentInspection.IntegrationTests;

public sealed class SecurityAdministrationHttpTests
{
    private static readonly PermissionAssignmentDto EquipmentView = new("catalog", "example.equipment", "view");

    [Theory]
    [InlineData("administrator")]
    [InlineData("application-administrator")]
    public async Task Both_administrators_manage_users_with_real_identity_provider_and_retained_audit(string username)
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        if (username == "application-administrator")
        {
            await host.LinkUserAsync(username, true, InspectionHost.AdministratorRoleCode,
                "Renamed equipment supervisors");
        }

        using var admin = await host.CreateClientAsync(username);
        var role = await PostAsync<RoleDetailsDto>(admin, "/api/security/roles",
            new CreateRoleRequestDto("inspection.reviewers", "Inspection reviewers", null, [EquipmentView]));
        var user = await PostAsync<UserDetailsDto>(admin, "/api/security/users",
            new CreateUserRequestDto("new-reviewer@example.test", "New", "Reviewer", "New reviewer", true,
                null, false, [role.RoleId]));
        Assert.NotEqual(Guid.Empty, user.UserId);
        Assert.False(string.IsNullOrWhiteSpace(user.AuthSubject));
        Assert.True(user.IsActive);
        Assert.True(user.KeycloakEnabled);
        Assert.Equal(role.RoleId, Assert.Single(user.Roles).RoleId);

        var path = $"/api/security/users/{user.UserId}";
        using var update = await admin.PutAsJsonAsync(path,
            new UpdateUserRequestDto("renamed-reviewer@example.test", "Updated", "Reviewer",
                "Updated reviewer", true, null, false, [role.RoleId]));
        await EnsureSuccessAsync(update);
        var updated = (await update.Content.ReadFromJsonAsync<UserDetailsDto>())!;
        Assert.Equal(user.AuthSubject, updated.AuthSubject);
        Assert.Equal("renamed-reviewer@example.test", updated.Email);
        Assert.Equal("Updated reviewer", updated.DisplayName);
        Assert.True(updated.AccessVersion > user.AccessVersion);

        using var deactivate = await admin.PostAsync(path + "/deactivate", null);
        Assert.Equal(HttpStatusCode.NoContent, deactivate.StatusCode);
        var inactive = (await admin.GetFromJsonAsync<UserDetailsDto>(path))!;
        Assert.False(inactive.IsActive);
        Assert.False(inactive.KeycloakEnabled);
        using var reactivate = await admin.PostAsync(path + "/reactivate", null);
        Assert.Equal(HttpStatusCode.NoContent, reactivate.StatusCode);
        var active = (await admin.GetFromJsonAsync<UserDetailsDto>(path))!;
        Assert.True(active.IsActive);
        Assert.True(active.KeycloakEnabled);
        Assert.True(active.AccessVersion > inactive.AccessVersion);

        using var unassign = await admin.PutAsJsonAsync(path + "/roles", new ReplaceUserRolesRequestDto([]));
        Assert.Equal(HttpStatusCode.NoContent, unassign.StatusCode);
        var unassigned = (await admin.GetFromJsonAsync<UserDetailsDto>(path))!;
        Assert.Empty(unassigned.Roles);
        var effective = (await admin.GetFromJsonAsync<EffectiveAccessDto>(path + "/effective-access"))!;
        Assert.Equal(user.UserId, effective.UserId);
        Assert.Equal(unassigned.AccessVersion, effective.AccessVersion);
        Assert.NotEmpty(effective.Groups);
        Assert.All(effective.Groups.SelectMany(group => group.Resources), resource => Assert.Empty(resource.Actions));

        var audit = (await admin.GetFromJsonAsync<AuditLogPageDto>(
            $"/api/audit/entities/SecurityUser/{user.UserId}?limit=100", Json))!;
        foreach (var action in new[] { "create", "update", "deactivate", "reactivate", "roles.replace" })
            Assert.Contains(audit.Items, item => item.ActionCode == "security.user." + action);
    }

    [Fact]
    public async Task Role_permissions_activation_and_membership_update_current_effective_access()
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        await host.LinkUserAsync("reader", true, "inspection.initial", "Initial reader");
        using var admin = await host.CreateClientAsync("administrator");
        using var reader = await host.CreateClientAsync("reader");
        var initial = (await reader.GetFromJsonAsync<CurrentAccessDto>("/api/security/me/access"))!;
        var role = await PostAsync<RoleDetailsDto>(admin, "/api/security/roles",
            new CreateRoleRequestDto("inspection.reviewers", "Reviewers", "Test role", [EquipmentView, EquipmentView]));
        Assert.False(role.HasFullAccess);
        Assert.Equal(EquipmentView, Assert.Single(role.Permissions));
        using var assignment = await admin.PutAsJsonAsync($"/api/security/users/{initial.UserId}/roles",
            new ReplaceUserRolesRequestDto([role.RoleId]));
        Assert.Equal(HttpStatusCode.NoContent, assignment.StatusCode);
        var assigned = (await reader.GetFromJsonAsync<CurrentAccessDto>("/api/security/me/access"))!;
        Assert.True(assigned.AccessVersion > initial.AccessVersion);
        Assert.Contains(EquipmentView, assigned.Permissions);

        var path = $"/api/security/roles/{role.RoleId}";
        var details = (await admin.GetFromJsonAsync<RoleDetailsDto>(path))!;
        Assert.Equal(initial.UserId, Assert.Single(details.AssignedUsers).UserId);
        using var update = await admin.PutAsJsonAsync(path,
            new UpdateRoleRequestDto(role.Code, "Renamed reviewers", "Updated description", true, [EquipmentView]));
        await EnsureSuccessAsync(update);
        Assert.Equal("Renamed reviewers", (await update.Content.ReadFromJsonAsync<RoleDetailsDto>())!.Name);
        using var deactivate = await admin.PostAsync(path + "/deactivate", null);
        Assert.Equal(HttpStatusCode.NoContent, deactivate.StatusCode);
        var inactive = (await reader.GetFromJsonAsync<CurrentAccessDto>("/api/security/me/access"))!;
        Assert.DoesNotContain(EquipmentView, inactive.Permissions);
        Assert.True(inactive.AccessVersion > assigned.AccessVersion);
        using var reactivate = await admin.PostAsync(path + "/reactivate", null);
        Assert.Equal(HttpStatusCode.NoContent, reactivate.StatusCode);
        var restored = (await reader.GetFromJsonAsync<CurrentAccessDto>("/api/security/me/access"))!;
        Assert.Contains(EquipmentView, restored.Permissions);

        using var revoke = await admin.PutAsJsonAsync(path + "/permissions", new ReplaceRolePermissionsRequestDto([]));
        Assert.Equal(HttpStatusCode.NoContent, revoke.StatusCode);
        var revoked = (await reader.GetFromJsonAsync<CurrentAccessDto>("/api/security/me/access"))!;
        Assert.DoesNotContain(EquipmentView, revoked.Permissions);
        Assert.True(revoked.AccessVersion > restored.AccessVersion);
        var roles = (await admin.GetFromJsonAsync<RoleListItemDto[]>("/api/security/roles"))!;
        Assert.Equal(1, Assert.Single(roles, item => item.RoleId == role.RoleId).AssignedUsersCount);
        var audit = (await admin.GetFromJsonAsync<AuditLogPageDto>(
            $"/api/audit/entities/SecurityRole/{role.RoleId}?limit=100", Json))!;
        foreach (var action in new[] { "create", "update", "deactivate", "reactivate", "permissions.replace" })
            Assert.Contains(audit.Items, item => item.ActionCode == "security.role." + action);
    }

    [Fact]
    public async Task User_pages_bind_cursor_to_active_filter_and_administration_denies_ungranted_actors()
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        await host.LinkUserAsync("reader", true, "inspection.readers", "Readers");
        await host.LinkUserAsync("imitator", true, "inspection.observers", "Administrator");
        await host.LinkUserAsync("inactive-administrator", false, "inspection.disabled", "Disabled administrator");
        using var admin = await host.CreateClientAsync("administrator");
        var first = (await admin.GetFromJsonAsync<PageResponseDto<UserListItemDto>>(
            "/api/security/users?limit=1&isActive=true"))!;
        Assert.Single(first.Items);
        Assert.True(first.HasMore);
        Assert.False(string.IsNullOrWhiteSpace(first.NextCursor));
        var second = (await admin.GetFromJsonAsync<PageResponseDto<UserListItemDto>>(
            "/api/security/users?limit=1&isActive=true&cursor=" + Uri.EscapeDataString(first.NextCursor!)))!;
        Assert.Single(second.Items);
        Assert.NotEqual(first.Items[0].UserId, second.Items[0].UserId);
        using var changedFilter = await admin.GetAsync(
            "/api/security/users?limit=1&isActive=false&cursor=" + Uri.EscapeDataString(first.NextCursor!));
        Assert.Equal(HttpStatusCode.BadRequest, changedFilter.StatusCode);
        var definitions = (await admin.GetFromJsonAsync<PermissionDefinitionDto[]>("/api/security/permissions/definitions"))!;
        Assert.Contains(definitions, item => item.ResourceCode == "example.inspection" && item.ActionCode == "approve");

        foreach (var username in new[] { "reader", "imitator", "inactive-administrator" })
        {
            using var actor = await host.CreateClientAsync(username);
            foreach (var endpoint in new[] { "/users", "/roles", "/permissions/definitions" })
            {
                using var denied = await actor.GetAsync("/api/security" + endpoint);
                Assert.Equal(HttpStatusCode.Forbidden, denied.StatusCode);
            }
            using var createRole = await actor.PostAsJsonAsync("/api/security/roles",
                new CreateRoleRequestDto("forbidden.role", "Forbidden", null, []));
            Assert.Equal(HttpStatusCode.Forbidden, createRole.StatusCode);
            using var createUser = await actor.PostAsJsonAsync("/api/security/users",
                new CreateUserRequestDto("forbidden@example.test", null, null, null, true, null, false, []));
            Assert.Equal(HttpStatusCode.Forbidden, createUser.StatusCode);
        }
        using var anonymous = host.CreateAnonymousClient();
        using var unauthenticated = await anonymous.GetAsync("/api/security/users");
        Assert.Equal(HttpStatusCode.Unauthorized, unauthenticated.StatusCode);
    }

    [Fact]
    public async Task Registered_administrator_role_code_and_implicit_permissions_are_protected()
    {
        await using var host = new InspectionHost();
        await host.StartAsync();
        await host.LinkUserAsync("application-administrator", true, InspectionHost.AdministratorRoleCode,
            "Renamed equipment supervisors");
        using var admin = await host.CreateClientAsync("administrator");
        var roles = (await admin.GetFromJsonAsync<RoleListItemDto[]>("/api/security/roles"))!;
        var role = Assert.Single(roles, item => item.Code == InspectionHost.AdministratorRoleCode);
        var path = $"/api/security/roles/{role.RoleId}";
        var details = (await admin.GetFromJsonAsync<RoleDetailsDto>(path))!;
        Assert.True(details.HasFullAccess);
        Assert.Contains(details.Permissions, item => item.ResourceCode == "example.inspection" && item.ActionCode == "approve");

        using var deactivate = await admin.PostAsync(path + "/deactivate", null);
        await AssertErrorAsync(deactivate, HttpStatusCode.Conflict, "ngb.security.administrator_role_protected");
        using var permissions = await admin.PutAsJsonAsync(path + "/permissions", new ReplaceRolePermissionsRequestDto([]));
        await AssertErrorAsync(permissions, HttpStatusCode.Conflict, "ngb.security.administrator_role_protected");
        using var renameCode = await admin.PutAsJsonAsync(path,
            new UpdateRoleRequestDto("inspection.demoted", "Changed", null, true, null));
        await AssertErrorAsync(renameCode, HttpStatusCode.Conflict, "ngb.security.administrator_role_protected");
        using var reserved = await admin.PostAsJsonAsync("/api/security/roles",
            new CreateRoleRequestDto(InspectionHost.AdministratorRoleCode, "Imitator", null, []));
        await AssertErrorAsync(reserved, HttpStatusCode.Conflict, "ngb.security.administrator_role_protected");

        using var renameDisplay = await admin.PutAsJsonAsync(path,
            new UpdateRoleRequestDto(role.Code, "Application owners", null, true, null));
        await EnsureSuccessAsync(renameDisplay);
        var renamed = (await renameDisplay.Content.ReadFromJsonAsync<RoleDetailsDto>())!;
        Assert.True(renamed.HasFullAccess);
        Assert.Equal(role.Code, renamed.Code);
        Assert.Equal("Application owners", renamed.Name);
    }
}

using System.Globalization;
using System.Net;
