                    webOrigins = new[] { "+" }
                },
                new
                {
                    clientId = "ngb-test-administration",
                    enabled = true,
                    protocol = "openid-connect",
                    publicClient = false,
                    secret = _adminClientSecret,
                    serviceAccountsEnabled = true,
                    standardFlowEnabled = false,
                    directAccessGrantsEnabled = false
                }
            },
            users = new[]
            {
                User("administrator", ["ngb-admin"]),
                User("application-administrator", []),
                User("imitator", []),
                User("inactive-administrator", ["ngb-admin"]),
                User("reader", []),
                new
                {
                    username = "service-account-ngb-test-administration",
                    enabled = true,
                    serviceAccountClientId = "ngb-test-administration",
                    clientRoles = new Dictionary<string, string[]>
                    {
                        ["realm-management"] = ["manage-users", "query-users", "view-users"]
                    }
                }
            }
        };
    }

    public async Task StartAsync()
    {
        _infrastructure = await TestInfrastructure.GetAsync();
        await _infrastructure.CreateRealmAsync(_realmDefinition);
        _created = true;
    }

    public string Subject(string username) => _subjects[username];

    public async Task<string> TokenAsync(string username)
    {
        using var client = new HttpClient { Timeout = TimeSpan.FromSeconds(30) };
        using var body = new FormUrlEncodedContent(new Dictionary<string, string>
        {
            ["client_id"] = ClientId,
            ["grant_type"] = "password",
            ["username"] = username,
            ["password"] = _password
        });
        using var response = await client.PostAsync($"{Issuer}/protocol/openid-connect/token", body);
        response.EnsureSuccessStatusCode();
        var token = await response.Content.ReadFromJsonAsync<JsonElement>();
        return token.GetProperty("access_token").GetString()!;
    }

    public async Task<string> AuthorizationCodeTokenAsync(string username)
    {
        const string redirect = "http://127.0.0.1/mcp-callback";
        var verifier = WebEncoders.Base64UrlEncode(RandomNumberGenerator.GetBytes(32));
        var state = WebEncoders.Base64UrlEncode(RandomNumberGenerator.GetBytes(24));
        using var handler = new HttpClientHandler { AllowAutoRedirect = false };
        using var client = new HttpClient(handler) { Timeout = TimeSpan.FromSeconds(30) };
        var authorization = QueryHelpers.AddQueryString($"{Issuer}/protocol/openid-connect/auth", new Dictionary<string, string?>
        {
            ["client_id"] = ClientId,
            ["response_type"] = "code",
            ["scope"] = "openid",
            ["redirect_uri"] = redirect,
            ["state"] = state,
            ["code_challenge"] = WebEncoders.Base64UrlEncode(SHA256.HashData(Encoding.ASCII.GetBytes(verifier))),
            ["code_challenge_method"] = "S256"
        });
        using var login = await client.GetAsync(authorization);
        login.EnsureSuccessStatusCode();
        // Browsers send Secure cookies to trustworthy loopback HTTP origins. HttpClient
        // does not; apply that exception only inside this disposable local fixture.
        Assert.True(new Uri(Issuer).IsLoopback);
        foreach (Cookie cookie in handler.CookieContainer.GetAllCookies())
            cookie.Secure = false;

        var html = await login.Content.ReadAsStringAsync();
        var form = Regex.Match(html, "<form\\b[^>]*\\bid=\"kc-form-login\"[^>]*\\baction=\"([^\"]+)\"",
            RegexOptions.CultureInvariant, TimeSpan.FromSeconds(1));
        Assert.True(form.Success, "The pinned identity provider must expose its login form.");
        var action = new Uri(WebUtility.HtmlDecode(form.Groups[1].Value));
        Assert.Equal(new Uri(Issuer).Authority, action.Authority);
        using var credentials = new FormUrlEncodedContent(new Dictionary<string, string>
        {
            ["username"] = username,
            ["password"] = _password,
            ["credentialId"] = ""
        });
        using var authenticated = await client.PostAsync(action, credentials);
        if (authenticated.StatusCode != HttpStatusCode.Redirect)
        {
            var rejected = await authenticated.Content.ReadAsStringAsync();
            var message = Regex.Match(rejected, "<div id=\"kc-error-message\">(.*?)</div>",
                RegexOptions.Singleline, TimeSpan.FromSeconds(1)).Groups[1].Value;
            Assert.Fail("Identity login failed: " + Regex.Replace(message, "<[^>]+>", "", RegexOptions.None, TimeSpan.FromSeconds(1)));
        }
        var callback = authenticated.Headers.Location!;
        Assert.Equal(redirect, callback.GetLeftPart(UriPartial.Path));
        var parameters = QueryHelpers.ParseQuery(callback.Query);
        Assert.Equal(state, parameters["state"].ToString());
        Assert.False(string.IsNullOrWhiteSpace(parameters["code"]));
        using var exchange = new FormUrlEncodedContent(new Dictionary<string, string>
        {
            ["grant_type"] = "authorization_code",
            ["client_id"] = ClientId,
            ["redirect_uri"] = redirect,
            ["code"] = parameters["code"].ToString(),
            ["code_verifier"] = verifier
        });
        using var response = await client.PostAsync($"{Issuer}/protocol/openid-connect/token", exchange);
        response.EnsureSuccessStatusCode();
        var token = await response.Content.ReadFromJsonAsync<JsonElement>();
        return token.GetProperty("access_token").GetString()!;
    }

    public async ValueTask DisposeAsync()
    {
        if (_created)
        {
            await _infrastructure!.DeleteRealmAsync(_realm);
            _created = false;
        }
    }

    private object User(string username, string[] roles)
    {
        var subject = Guid.NewGuid().ToString();
        _subjects.Add(username, subject);
        return new
        {
            id = subject,
            username,
            firstName = "Test",
            lastName = username,
            email = username + "@example.test",
            enabled = true,
            emailVerified = true,
            realmRoles = roles,
            credentials = new[] { new { type = "password", value = _password, temporary = false } }
        };
    }
}

using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text.Json;
using DotNet.Testcontainers.Builders;
using DotNet.Testcontainers.Containers;
using Npgsql;
using Testcontainers.PostgreSql;

namespace EquipmentInspection.IntegrationTests;

internal sealed class TestInfrastructure : IAsyncDisposable
{
    private static readonly object Gate = new();
    private static Task<TestInfrastructure>? _instance;

    private readonly PostgreSqlContainer _postgres = new PostgreSqlBuilder("postgres:16-alpine").Build();
    private readonly string _password = Convert.ToHexString(RandomNumberGenerator.GetBytes(32));
    private readonly IContainer _keycloak;
    private readonly HttpClient _client = new() { Timeout = TimeSpan.FromSeconds(30) };

    private TestInfrastructure()
    {
        _keycloak = new ContainerBuilder("quay.io/keycloak/keycloak:26.5.6")
            .WithPortBinding(8080, true)
            .WithEnvironment("KC_BOOTSTRAP_ADMIN_USERNAME", "fixture-admin")
            .WithEnvironment("KC_BOOTSTRAP_ADMIN_PASSWORD", _password)
            .WithCommand("start-dev", "--hostname-strict=false")
            .WithWaitStrategy(Wait.ForUnixContainer().UntilHttpRequestIsSucceeded(request => request
                .ForPort(8080).ForPath("/realms/master/.well-known/openid-configuration")))
            .Build();
    }

    public string IdentityOrigin => $"http://{_keycloak.Hostname}:{_keycloak.GetMappedPublicPort(8080)}";

    public static Task<TestInfrastructure> GetAsync()
    {
        lock (Gate)
        {
            return _instance ??= StartAsync();
        }
    }

    public static async Task ShutdownAsync()
    {
        Task<TestInfrastructure>? instance;
        lock (Gate)
        {
            instance = _instance;
            _instance = null;
        }

        if (instance is not null)
            await (await instance).DisposeAsync();
    }

    public async Task<TestDatabase> CreateDatabaseAsync()
    {
        var name = "inspection_" + Guid.NewGuid().ToString("N");
        await using var connection = new NpgsqlConnection(_postgres.GetConnectionString());
        await connection.OpenAsync();
        // The identifier is generated here, never supplied by an application or agent.
        await using var command = new NpgsqlCommand($"CREATE DATABASE \"{name}\"", connection);
        await command.ExecuteNonQueryAsync();
        var settings = new NpgsqlConnectionStringBuilder(_postgres.GetConnectionString()) { Database = name };
        return new TestDatabase(_postgres.GetConnectionString(), settings.ConnectionString, name);
    }

    public async Task CreateRealmAsync(object realm)
    {
        using var request = new HttpRequestMessage(HttpMethod.Post, "admin/realms")
        {
            Content = JsonContent.Create(realm)
        };
        using var response = await SendAdministrationAsync(request);
        response.EnsureSuccessStatusCode();
    }

    public async Task DeleteRealmAsync(string realm)
    {
        using var request = new HttpRequestMessage(HttpMethod.Delete, "admin/realms/" + Uri.EscapeDataString(realm));
        using var response = await SendAdministrationAsync(request);
        if (response.StatusCode != HttpStatusCode.NotFound)
            response.EnsureSuccessStatusCode();
    }

    public async ValueTask DisposeAsync()
    {
        _client.Dispose();
        try
        {
            await _keycloak.DisposeAsync();
        }
        finally
        {
            await _postgres.DisposeAsync();
        }
    }

    private static async Task<TestInfrastructure> StartAsync()
    {
        var infrastructure = new TestInfrastructure();
        try
        {
            await Task.WhenAll(infrastructure._postgres.StartAsync(), infrastructure._keycloak.StartAsync());
            infrastructure._client.BaseAddress = new Uri(infrastructure.IdentityOrigin + "/");
            return infrastructure;
        }
        catch
        {
            await infrastructure.DisposeAsync();
            throw;
        }
    }

    private async Task<HttpResponseMessage> SendAdministrationAsync(HttpRequestMessage request)
    {
        using var credentials = new FormUrlEncodedContent(new Dictionary<string, string>
        {
            ["client_id"] = "admin-cli",
            ["grant_type"] = "password",
            ["username"] = "fixture-admin",
            ["password"] = _password
        });
        using var authentication = await _client.PostAsync("realms/master/protocol/openid-connect/token", credentials);
        authentication.EnsureSuccessStatusCode();
        var token = await authentication.Content.ReadFromJsonAsync<JsonElement>();
        request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", token.GetProperty("access_token").GetString());
        return await _client.SendAsync(request);
    }
}

internal sealed class TestDatabase(string administrationConnection, string connectionString, string name) : IAsyncDisposable
{
    public string ConnectionString => connectionString;

    public async ValueTask DisposeAsync()
    {
        await using var pooledConnection = new NpgsqlConnection(connectionString);
        NpgsqlConnection.ClearPool(pooledConnection);
        await using var connection = new NpgsqlConnection(administrationConnection);
        await connection.OpenAsync();
        await using var command = new NpgsqlCommand($"DROP DATABASE IF EXISTS \"{name}\" WITH (FORCE)", connection);
        await command.ExecuteNonQueryAsync();
    }
}

using System.Net;
using NGB.Contracts.Services;
using Npgsql;
using Xunit;
using static EquipmentInspection.IntegrationTests.InspectionRequests;

namespace EquipmentInspection.IntegrationTests;

public sealed class TestInfrastructureTests
{
    [Fact]
    public async Task Parallel_hosts_share_servers_but_isolate_databases_realms_and_tokens()
    {
        await using var first = new InspectionHost();
        await using var second = new InspectionHost();
        await Task.WhenAll(first.StartAsync(), second.StartAsync());
        var firstDatabase = new NpgsqlConnectionStringBuilder(first.ConnectionString);
        var secondDatabase = new NpgsqlConnectionStringBuilder(second.ConnectionString);
        Assert.Equal(firstDatabase.Host, secondDatabase.Host);
        Assert.Equal(firstDatabase.Port, secondDatabase.Port);
        Assert.NotEqual(firstDatabase.Database, secondDatabase.Database);
        Assert.Equal(new Uri(first.IdentityIssuer).Authority, new Uri(second.IdentityIssuer).Authority);
        Assert.NotEqual(first.IdentityIssuer, second.IdentityIssuer);

        using var firstAdmin = await first.CreateClientAsync("administrator");
        using var secondAdmin = await second.CreateClientAsync("administrator");
        var equipment = await PostAsync<CatalogItemDto>(firstAdmin, "/api/catalogs/example.equipment",
            Payload(("display", "Isolated equipment")));
        using var absent = await secondAdmin.GetAsync($"/api/catalogs/example.equipment/{equipment.Id}");
        Assert.Equal(HttpStatusCode.NotFound, absent.StatusCode);

        using var foreignToken = second.CreateAnonymousClient();
        foreignToken.DefaultRequestHeaders.Authorization = firstAdmin.DefaultRequestHeaders.Authorization;
        using var denied = await foreignToken.GetAsync("/api/example-access/registered-permission");
        Assert.Equal(HttpStatusCode.Unauthorized, denied.StatusCode);
        using var allowed = await secondAdmin.GetAsync("/api/example-access/registered-permission");
        await EnsureSuccessAsync(allowed);
    }

    [Fact]
    public async Task Disposing_one_host_removes_its_resources_and_preserves_another_host()
    {
        var first = new InspectionHost();
        string connectionString;
        string issuer;
        await using var second = new InspectionHost();
        await using (first)
        {
            await Task.WhenAll(first.StartAsync(), second.StartAsync());
            connectionString = first.ConnectionString;
            issuer = first.IdentityIssuer;
        }

        using var client = new HttpClient();
        using var deleted = await client.GetAsync(issuer + "/.well-known/openid-configuration");
        Assert.Equal(HttpStatusCode.NotFound, deleted.StatusCode);
        await using var connection = new NpgsqlConnection(connectionString);
        var error = await Assert.ThrowsAsync<PostgresException>(() => connection.OpenAsync());
        Assert.Equal(PostgresErrorCodes.InvalidCatalogName, error.SqlState);

        using var admin = await second.CreateClientAsync("administrator");
        using var permission = await admin.GetAsync("/api/example-access/registered-permission");
        await EnsureSuccessAsync(permission);
    }
}

using System.Net.Http.Json;
using System.Text.Json;
using EquipmentInspection.Definitions;
using Microsoft.Extensions.DependencyInjection;
using NGB.Contracts.Common;
using NGB.Contracts.Documents;
using NGB.Contracts.Metadata;
using NGB.Contracts.Services;
